describe('Filter Tag Removal', () => {
    beforeEach(() => {
        cy.visit('/search'); // Adjust the URL to your application's search page
    });

    it('should remove a filter tag when the x icon is clicked', () => {
        // Assuming a filter tag with the text 'Example Tag' exists
        cy.get('.filter-tag').contains('Example Tag').should('exist');
        cy.get('.filter-tag').contains('Example Tag').find('.remove-icon').click();
        cy.get('.filter-tag').contains('Example Tag').should('not.exist');
    });

    it('should not remove any filter tags if the x icon is clicked on a non-existing tag', () => {
        // Click the x icon on a tag that does not exist
        cy.get('.filter-tag').contains('Non-Existing Tag').find('.remove-icon').click();
        cy.get('.filter-tag').should('have.length.greaterThan', 0); // Ensure at least one tag still exists
    });
});
